"""Apply reviewed chapters to existing geometry. Never re-route or upload a rider's GPX.
After running, render-starter-guides.mjs creates all included audio without API keys.
Distances mark chapters: contextual chapters do not claim their subject is at that point.
"""
import hashlib, json, uuid
from pathlib import Path
FILE = Path(__file__).resolve().parents[1] / 'backend/routes/starter-routes.json'

def c(km, title, photo, text, url):
    assert 30 <= len(text) <= 650, (title, len(text))
    return dict(distanceKm=km, title=title, photoTitle=photo, text=text, sources=[dict(title=title+' — historical source', url=url)])

